import compare


def test_connection_counts():
    results = compare.run_comparison()
    assert results["count_a"] == 50, (
        f"client A should have used 50 connections, got {results['count_a']}"
    )
    assert results["count_b"] < 5, (
        f"client B should have used fewer than 5 connections, got {results['count_b']}"
    )
